param([ValidateRange(1024,65535)][int]$Port=4173)
$ErrorActionPreference="Stop";$root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path;$prefix="http://127.0.0.1:$Port/";$types=@{".css"="text/css; charset=utf-8";".html"="text/html; charset=utf-8";".js"="text/javascript; charset=utf-8";".json"="application/json; charset=utf-8";".png"="image/png";".svg"="image/svg+xml";".webmanifest"="application/manifest+json; charset=utf-8"};$listener=[System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback,$Port);$listener.Start();Write-Host "刑訴条文ナビを $prefix で配信しています。Ctrl+Cで停止します。"
try{while($true){$client=$listener.AcceptTcpClient();try{$stream=$client.GetStream();$reader=[IO.StreamReader]::new($stream,[Text.Encoding]::ASCII,$false,4096,$true);$line=$reader.ReadLine();while($reader.ReadLine()){};$status="200 OK";$bytes=[byte[]]@();$contentType="text/plain; charset=utf-8";if($line -notmatch "^GET\s+([^\s]+)\s+HTTP/"){$status="405 Method Not Allowed"}else{$target=[Uri]::UnescapeDataString($Matches[1].Split("?")[0]);$path=$target.TrimStart("/");if([string]::IsNullOrWhiteSpace($path)){$path="index.html"};$file=[IO.Path]::GetFullPath((Join-Path $root $path));if(-not $file.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)-or -not(Test-Path -LiteralPath $file -PathType Leaf)){$status="404 Not Found"}else{$ext=[IO.Path]::GetExtension($file).ToLowerInvariant();$contentType=if($types.ContainsKey($ext)){$types[$ext]}else{"application/octet-stream"};$bytes=[IO.File]::ReadAllBytes($file)}};$header="HTTP/1.1 $status`r`nContent-Type: $contentType`r`nContent-Length: $($bytes.Length)`r`nCache-Control: no-cache`r`nConnection: close`r`n`r`n";$head=[Text.Encoding]::ASCII.GetBytes($header);$stream.Write($head,0,$head.Length);if($bytes.Length -gt 0){$stream.Write($bytes,0,$bytes.Length)};$stream.Flush()}finally{$client.Close()}}}finally{$listener.Stop()}
